from swimlane import Map
m=Map("Part 2 — Win the Work: Pipeline to Contract",
      "Level-1 cross-functional map · as specified · account to signed contract · gates 6, 7, 9, 10 · hard block 6 · 8 September 2026",
      [("client","Client"),("exec","Executive"),("sales","Sales and Pipeline"),("proj","Projects and Site"),("platform","The Platform")])
s=m.step
s("2.1","sales","Create account, contact and site",rec="parties · contacts · sites")
s("2.2","sales","Create opportunity",rec="opportunities",state="prospect")
s("2.3","sales","Start assessment",rec="opportunities",state="assessing")
s("2.4","client","Grants site access · shares load data",kind="external",col=2)
s("2.5","sales","Record site assessment",rec="site_assessments",state="proceed | conditions | do not proceed",dev="accepts a future date (1-09)")
s("2.6","sales","Proceed?",kind="decision")
s("2.7","sales","Mark lost or on hold",rec="opportunities",state="lost | on_hold",col=5)
s("2.8","sales","Create proposal",rec="proposals",state="draft · opp: proposing",col=6)
s("2.9","sales","Submit for internal review",rec="proposals",state="submitted_for_review")
s("2.10","exec","Review proposal",rec="approval_requests",state="approved | rejected",gate=("6","Director","COO",None),dev="RC-A raiser can approve own request")
s("2.11","sales","Send to client",rec="proposals",state="sent_to_client",dev="no confirmation before it leaves (1-20)")
s("2.12","client","Reviews · negotiates · accepts or declines",kind="external",rec="proposals",state="under_negotiation → accepted | declined",col=9)
s("2.13","sales","Submit for won decision",rec="opportunities",state="negotiating",col=10)
s("2.14","exec","Decide won",rec="approval_requests",state="won | rejected",gate=("7","Director",None,None),dev="G7 is specified as conditional: markup >5 points below policy. Live raises it on every won")
s("2.15","platform","Project created · proposal frozen · eight risk terms seeded",kind="auto",rec="projects [setup] · proposals [frozen] · risk_terms [not_yet_read]")
s("2.16","proj","Create contract",rec="contracts",state="draft")
s("2.17","client","Signs agreement",kind="external",col=13)
s("2.18","proj","Attach signed contract",rec="contracts · projects.contractSignedAt",gate=("9","CEO",None,None),dev="G9 specified, not enforced · signed date accepts the future (1-08)",col=14)
s("2.19","proj","Acknowledge risk terms · risk review",rec="risk_terms",state="acknowledged | accepted | rejected",gate=("10","Director","COO",None),dev="G10 specified, not enforced · terms show no text to read (1-23)")
s("2.20","proj","Assign project parties",rec="project_parties",state="ten seat roles",dev="mutation exists; no control in the interface (1-04)")
s("2.21","platform","Advance from setup",kind="auto",rec="projects",state="design",hb=("HB6","no signed contract, project cannot leave setup"))
for a,b in [("2.1","2.2"),("2.2","2.3"),("2.3","2.5"),("2.4","2.5"),("2.5","2.6"),("2.6","2.8"),("2.8","2.9"),("2.9","2.10"),("2.10","2.11"),("2.11","2.12"),("2.12","2.13"),("2.13","2.14"),("2.14","2.15"),("2.15","2.16"),("2.16","2.17"),("2.17","2.18"),("2.18","2.19"),("2.19","2.20"),("2.20","2.21")]: m.edge(a,b)
m.edge("2.6","2.7","no",kind="return"); m.edge("2.10","2.8","rejected: back to draft",kind="return"); m.edge("2.14","2.8","rejected: back to proposing",kind="return")
m.banner="RC-A one same-person check in sixteen approvals · G7 raised on every won decision, specified as conditional · G9 and G10 specified but never raised in code · project parties: mutation exists, no control · future dates accepted on assessment and signature"
info=m.render("part2.svg"); print(info)
svg=open("part2.svg").read()
import re; w,h=re.search(r'width="(\d+)" height="(\d+)"',svg).groups()
open("part2.html","w").write(f'<!doctype html><html><head><meta charset="utf-8"><style>@page{{size:A3 landscape;margin:5mm}} html,body{{margin:0;background:#fff}} svg{{width:{w}px;height:{h}px;display:block}}</style></head><body>'+svg+'</body></html>')
print("canvas",w,"x",h)
